#!/usr/bin/env node
// Regenerates assets/offline-bundle.js: the SVG rigs (as text) and the title fonts (base64).
// Browsers block fetch() and @font-face for pages opened straight from disk (file://), so
// main.js falls back to these inlined copies there. When the page is served over http(s)
// the real files in assets/ are used, so edits to the SVGs show up without rebuilding.
//
//   node tools/build-offline-bundle.mjs           write assets/offline-bundle.js
//   node tools/build-offline-bundle.mjs --check   exit 1 if the bundle is out of date
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const svgs = ['kids-original.svg', 'baby-elephant.svg', 'diya.svg', 'sparkler-and-chakri.svg'];
const fonts = ['fredoka-latin-600-normal.woff2', 'fredoka-latin-700-normal.woff2', 'baloo-2-latin-700-normal.woff2', 'baloo-2-latin-800-normal.woff2'];
const out = join(root, 'assets', 'offline-bundle.js');

const svgEntries = svgs.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(join(root, 'assets', f), 'utf8'))}`);
const fontEntries = fonts.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(join(root, 'assets', 'fonts', f)).toString('base64'))}`);
const js = '// Generated by tools/build-offline-bundle.mjs from assets/*.svg and assets/fonts/*.woff2. Do not edit by hand.\n' +
  '// Fonts: Fredoka and Baloo 2, SIL Open Font License 1.1 (see assets/fonts/OFL-*.txt).\n' +
  `window.DIWALI_SVG_BUNDLE = {\n${svgEntries.join(',\n')}\n};\n` +
  `window.DIWALI_FONT_BUNDLE = {\n${fontEntries.join(',\n')}\n};\n`;

if (process.argv.includes('--check')) {
  const current = existsSync(out) ? readFileSync(out, 'utf8') : '';
  if (current !== js) {
    console.error('assets/offline-bundle.js is out of date. Run: node tools/build-offline-bundle.mjs');
    process.exit(1);
  }
  console.log('assets/offline-bundle.js is up to date.');
} else {
  writeFileSync(out, js);
  console.log(`Wrote ${out} (${svgs.length} SVGs, ${fonts.length} fonts, ${(js.length / 1024).toFixed(1)} KB)`);
}
